fn the_liveness_schedule_has_early_and_late_deadlines() {
        // Early deadlines land inside the short E3 window; the late ones are the
        // record gap S1 asks for, so a reader can cite "still advancing frames
        // long after the battery's last step".
        assert_eq!(next_deadline_ms(0), 2_000, "the first record is early");
        assert_eq!(next_deadline_ms(6), 60_000, "the last fixed one is late");
        assert_eq!(
            next_deadline_ms(7),
            60_000 + LIVENESS_INTERVAL_MS,
            "after the fixed schedule it keeps repeating"
        );
        assert!(
            next_deadline_ms(6) >= 30_000,
            "there is a deadline several seconds after the early window"
        );

        // How many deadlines have come due.
        assert_eq!(records_due(0, 0), 0, "nothing is due at launch");
        assert_eq!(records_due(0, 1_999), 0);
        assert_eq!(records_due(0, 2_000), 1, "the first deadline is 2 s");
        assert_eq!(records_due(0, 5_000), 2, "2 s and 4 s are both due");
        assert_eq!(records_due(0, 60_000), 7, "all fixed deadlines are due");
        assert_eq!(records_due(0, 90_000), 8, "then one per interval");
        assert_eq!(
            records_due(3, 0),
            3,
            "a suspended process never rewinds the count"
        );
        assert_eq!(
            records_due(0, u64::MAX),
            7 + (u64::MAX - 60_000) / LIVENESS_INTERVAL_MS,
            "a huge clock jump is computed in closed form, not by stepping"
        );
    }

