    #[test]
    fn the_tool_shaped_reads_land_in_their_own_files() {
        // Plan priority 1 names two reads: `bevy_health` and
        // `bevy_player_transform`.  Both are persisted, both are stamped with
        // the game's own frame counter, and both append rather than truncate, so
        // several seconds of liveness accumulate.
        let dir = std::env::temp_dir().join("hof_game_tool_reads_test");
        let _ = std::fs::remove_dir_all(&dir);
        persist_tool_reads(&dir, 720, 4242, 1_700_000_000_000, 100.0, -200.0, true);
        persist_tool_reads(&dir, 780, 4242, 1_700_000_001_000, 100.0, -200.0, true);

        let health = std::fs::read_to_string(dir.join(LIVENESS_HEALTH_NAME)).unwrap();
        let transform = std::fs::read_to_string(dir.join(LIVENESS_TRANSFORM_NAME)).unwrap();
        assert_eq!(health.lines().count(), 2, "the health read must append");
        assert_eq!(transform.lines().count(), 2, "the transform read must append");
