        assert!(health.contains("\"frame\":780"), "stamped with the game frame");
        assert!(
            transform.contains("\"frame\":780"),
            "the transform read is stamped with the game frame"
        );
        assert!(
            transform.contains("\"x\":100.00"),
            "the transform read carries the player's x: {transform}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
}
